--
-- Table structure for table `group_buys`
--

DROP TABLE IF EXISTS `group_buys`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `group_buys` (
  `group_buy_id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `seller_id` bigint NOT NULL,
  `product_price` bigint NOT NULL,
  `target_participants` int NOT NULL COMMENT '최소 2명',
  `unit_share_amount` bigint NOT NULL COMMENT '확정 분담금, 불변',
  `shipping_fee` bigint NOT NULL COMMENT '판매자 기입',
  `return_shipping_fee` bigint GENERATED ALWAYS AS ((`shipping_fee` * 2)) STORED COMMENT '왕복이므로 배송비의 2배',
  `rounding_diff` bigint NOT NULL DEFAULT '0' COMMENT '절상 차액',
  `platform_fee_rate` decimal(5,4) NOT NULL DEFAULT '0.0500' COMMENT '정률 5%, 상품 분담금 기준 (배송비 제외)',
  `expected_platform_fee` bigint NOT NULL,
  `expected_settlement_amount` bigint NOT NULL,
  `recruit_start_at` datetime NOT NULL,
  `recruit_end_at` datetime NOT NULL,
  `current_participants` int NOT NULL DEFAULT '0' COMMENT '결제 완료(PAID) 참여 수',
  `reserved_slots` int NOT NULL DEFAULT '0' COMMENT '결제 진행중(PROCESSING) 건 수',
  `fulfilled_at` datetime DEFAULT NULL,
  `shipping_deadline_at` datetime DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'RECRUITING' COMMENT 'RECRUITING/FULFILLED/SHIPPING/DELIVERED/COMPLETED/SETTLED/FAILED/CANCELED',
  `version` bigint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`group_buy_id`),
  KEY `idx_group_buys_status_end` (`status`,`recruit_end_at`),
  KEY `idx_group_buys_seller` (`seller_id`,`status`),
  KEY `idx_group_buys_deadline` (`status`,`shipping_deadline_at`),
  KEY `idx_group_buys_product` (`product_id`),
  CONSTRAINT `fk_group_buys_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`),
  CONSTRAINT `fk_group_buys_seller` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`seller_id`),
  CONSTRAINT `ck_group_buys_slots` CHECK (((`current_participants` + `reserved_slots`) <= `target_participants`)),
  CONSTRAINT `ck_group_buys_target` CHECK ((`target_participants` >= 2))
) ENGINE=InnoDB AUTO_INCREMENT=304 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='공동구매';
/*!40101 SET character_set_client = @saved_cs_client */;

