--
-- Table structure for table `kakaopay_cancellations`
--

DROP TABLE IF EXISTS `kakaopay_cancellations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kakaopay_cancellations` (
  `idempotency_key` varchar(64) NOT NULL,
  `payment_id` bigint NOT NULL,
  `tid` varchar(100) NOT NULL,
  `requested_amount` bigint NOT NULL,
  `status` varchar(20) NOT NULL COMMENT 'PENDING/SUCCEEDED/FAILED/UNKNOWN',
  `cancel_aid` varchar(100) DEFAULT NULL,
  `approved_cancel_amount` bigint DEFAULT NULL,
  `canceled_amount` bigint DEFAULT NULL,
  `cancel_available_amount` bigint DEFAULT NULL,
  `failure_reason` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`idempotency_key`),
  KEY `idx_kakao_cancel_payment` (`payment_id`,`status`),
  KEY `idx_kakao_cancel_tid` (`tid`),
  CONSTRAINT `fk_kakao_cancel_payment` FOREIGN KEY (`payment_id`) REFERENCES `kakaopay_payments` (`payment_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='카카오페이 전체·부분 취소 멱등 요청';
/*!40101 SET character_set_client = @saved_cs_client */;

