--
-- Table structure for table `kakaopay_payments`
--

DROP TABLE IF EXISTS `kakaopay_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kakaopay_payments` (
  `payment_id` bigint NOT NULL,
  `tid` varchar(100) DEFAULT NULL COMMENT '결제 준비 응답 TID',
  `aid` varchar(100) DEFAULT NULL COMMENT '승인 ID',
  `partner_order_id` varchar(100) DEFAULT NULL,
  `partner_user_id` varchar(100) DEFAULT NULL,
  `total_amount` bigint DEFAULT NULL,
  `tax_free_amount` bigint NOT NULL DEFAULT '0' COMMENT '모든 상품 과세 처리 → 항상 0',
  `vat_amount` bigint DEFAULT NULL COMMENT '카카오페이 자동 계산',
  `payment_method_type` varchar(20) DEFAULT NULL COMMENT 'CARD / MONEY',
  `next_redirect_pc_url` varchar(500) DEFAULT NULL COMMENT 'Ready 응답 PC 결제 이동 URL',
  `state_nonce` varchar(64) DEFAULT NULL COMMENT '리다이렉트 state 일회용 nonce',
  `state_expires_at` datetime DEFAULT NULL COMMENT 'state 만료 시각(결제 슬롯 만료와 동일)',
  `state_consumed_at` datetime DEFAULT NULL COMMENT '승인 시 state 소비 시각',
  `raw_response` json DEFAULT NULL,
  PRIMARY KEY (`payment_id`),
  KEY `idx_kakaopay_tid` (`tid`),
  CONSTRAINT `fk_kakaopay_payments_payment` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`payment_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='카카오페이 결제 상세';
/*!40101 SET character_set_client = @saved_cs_client */;

