--
-- Table structure for table `notifications`
--

DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `notification_id` bigint NOT NULL AUTO_INCREMENT,
  `recipient_type` varchar(10) NOT NULL COMMENT 'BUYER / SELLER',
  `recipient_id` bigint NOT NULL,
  `type` varchar(30) NOT NULL,
  `title` varchar(100) NOT NULL,
  `body` varchar(500) DEFAULT NULL,
  `link_url` varchar(255) DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `dedup_key` varchar(150) DEFAULT NULL COMMENT '이벤트 중복 알림 방지 키',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`notification_id`),
  UNIQUE KEY `uk_notifications_dedup` (`dedup_key`),
  KEY `idx_notifications_recipient` (`recipient_type`,`recipient_id`,`read_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='인앱 알림';
/*!40101 SET character_set_client = @saved_cs_client */;

