--
-- Table structure for table `participations`
--

DROP TABLE IF EXISTS `participations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `participations` (
  `participation_id` bigint NOT NULL AUTO_INCREMENT,
  `group_buy_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `share_amount` bigint NOT NULL COMMENT '분담금 스냅샷',
  `shipping_fee` bigint NOT NULL COMMENT '배송비 스냅샷',
  `total_amount` bigint NOT NULL COMMENT '개인 결제금액',
  `recipient_name` varchar(50) NOT NULL,
  `recipient_phone` varchar(20) NOT NULL,
  `zipcode` char(5) NOT NULL,
  `address1` varchar(255) NOT NULL,
  `address2` varchar(255) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PAID' COMMENT 'PAID/FULFILLED/SHIPPING/DELIVERED/CONFIRMED/SETTLED/CANCELED/RETURNING/RETURNED/REFUNDED',
  `joined_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `delivered_at` datetime DEFAULT NULL,
  `withdrawal_period_end_at` datetime DEFAULT NULL COMMENT '청약철회 종료 = 배송완료 + 7일',
  `settlement_eligible_at` datetime DEFAULT NULL COMMENT '정산 자격 시각. 수동 확정해도 이 시각 전에는 정산 불가',
  `confirmed_at` datetime DEFAULT NULL,
  `confirm_type` varchar(10) DEFAULT NULL COMMENT 'MANUAL / AUTO',
  `confirm_notice_agreed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '수동 확정 시 반품 제한 고지 동의',
  `confirm_hold` tinyint(1) NOT NULL DEFAULT '0' COMMENT '반품 진행 중 자동확정 보류',
  `settled` tinyint(1) NOT NULL DEFAULT '0',
  `active_marker` char(1) DEFAULT NULL COMMENT '활성 Y, 취소 시 NULL',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delivery_request` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`participation_id`),
  UNIQUE KEY `uk_participation_active` (`group_buy_id`,`user_id`,`active_marker`),
  KEY `idx_participation_group` (`group_buy_id`,`status`),
  KEY `idx_participation_user` (`user_id`,`status`),
  KEY `idx_participation_autoconfirm` (`status`,`confirm_hold`,`withdrawal_period_end_at`),
  KEY `idx_participation_settle` (`status`,`settled`,`settlement_eligible_at`),
  CONSTRAINT `fk_participation_group_buy` FOREIGN KEY (`group_buy_id`) REFERENCES `group_buys` (`group_buy_id`),
  CONSTRAINT `fk_participation_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='공동구매 참여';
/*!40101 SET character_set_client = @saved_cs_client */;

