--
-- Table structure for table `payments`
--

DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` bigint NOT NULL AUTO_INCREMENT,
  `group_buy_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `address_id` bigint DEFAULT NULL COMMENT '결제 시작 시 선택한 배송지. 승인 완료 시 참여 건 배송지의 출처',
  `participation_id` bigint DEFAULT NULL COMMENT '결제 완료 후 연결',
  `method` varchar(20) NOT NULL COMMENT 'CARD / KAKAOPAY / CRYPTO',
  `krw_amount` bigint NOT NULL COMMENT 'KRW 기준 거래가치',
  `slot_expires_at` datetime NOT NULL COMMENT '슬롯 만료. 카드·페이 5분, 코인 10분',
  `slot_marker` char(1) DEFAULT NULL COMMENT 'PROCESSING일 때 Y, 그 외 NULL (중복 선점 차단)',
  `idempotency_key` varchar(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PROCESSING' COMMENT 'PROCESSING(슬롯 점유) / PAID / FAILED / EXPIRED / REFUNDED',
  `approved_at` datetime DEFAULT NULL,
  `fail_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `card_approval_status` varchar(20) DEFAULT NULL,
  `card_institution_tx_no` varchar(20) DEFAULT NULL,
  `prepare_crypto_asset_id` bigint DEFAULT NULL,
  `shipping_recipient_name` varchar(50) DEFAULT NULL,
  `shipping_recipient_phone` varchar(20) DEFAULT NULL,
  `shipping_zipcode` varchar(5) DEFAULT NULL,
  `shipping_address1` varchar(255) DEFAULT NULL,
  `shipping_address2` varchar(255) DEFAULT NULL,
  `shipping_delivery_request` varchar(100) DEFAULT NULL,
  `prepare_delivery_request` varchar(100) DEFAULT NULL,
  `reconcile_state` varchar(20) DEFAULT NULL COMMENT '외부청구 성공+공구종료로 미확정된 결제의 재조정 상태(REFUND_REQUIRED 등)',
  PRIMARY KEY (`payment_id`),
  UNIQUE KEY `uk_payments_idempotency` (`idempotency_key`),
  UNIQUE KEY `uk_payments_participation` (`participation_id`),
  UNIQUE KEY `uk_payments_slot` (`group_buy_id`,`user_id`,`slot_marker`),
  KEY `idx_payments_slot_expire` (`status`,`slot_expires_at`),
  KEY `idx_payments_group` (`group_buy_id`,`status`),
  KEY `idx_payments_user` (`user_id`,`status`),
  KEY `idx_payments_address` (`address_id`),
  KEY `idx_payments_reconcile_state` (`reconcile_state`),
  CONSTRAINT `fk_payments_group_buy` FOREIGN KEY (`group_buy_id`) REFERENCES `group_buys` (`group_buy_id`),
  CONSTRAINT `fk_payments_participation` FOREIGN KEY (`participation_id`) REFERENCES `participations` (`participation_id`),
  CONSTRAINT `fk_payments_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='결제 공통 + 슬롯 선점. PROCESSING 상태가 곧 선점된 슬롯';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `payments`
--

LOCK TABLES `payments` WRITE;
/*!40000 ALTER TABLE `payments` DISABLE KEYS */;
