--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `product_id` bigint NOT NULL AUTO_INCREMENT,
  `seller_id` bigint NOT NULL,
  `category_id` bigint DEFAULT NULL COMMENT 'AI 추출',
  `name` varchar(200) NOT NULL COMMENT 'AI 추출',
  `brand` varchar(100) DEFAULT NULL COMMENT '판매자 직접 입력',
  `model_name` varchar(100) DEFAULT NULL COMMENT '판매자 직접 입력',
  `color` varchar(50) DEFAULT NULL COMMENT '판매자 직접 입력',
  `description` text,
  `price` bigint NOT NULL COMMENT '원 단위',
  `ai_extracted` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'AI 자동 등록 사용 여부',
  `withdrawal_restricted` tinyint(1) NOT NULL DEFAULT '0',
  `restriction_reason_id` bigint DEFAULT NULL,
  `restriction_evidence_url` varchar(500) DEFAULT NULL COMMENT '증빙자료',
  `restriction_review_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT 'NONE / PENDING / APPROVED / REJECTED',
  `restriction_reviewed_by` bigint DEFAULT NULL,
  `restriction_reviewed_at` datetime DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE / DELETED',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_id`),
  KEY `idx_products_seller` (`seller_id`,`status`),
  KEY `idx_products_category` (`category_id`,`status`),
  KEY `idx_products_restriction` (`restriction_review_status`),
  KEY `fk_products_restriction_reason` (`restriction_reason_id`),
  KEY `fk_products_restriction_admin` (`restriction_reviewed_by`),
  FULLTEXT KEY `ft_products_name` (`name`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `fk_products_restriction_admin` FOREIGN KEY (`restriction_reviewed_by`) REFERENCES `admins` (`admin_id`),
  CONSTRAINT `fk_products_restriction_reason` FOREIGN KEY (`restriction_reason_id`) REFERENCES `withdrawal_restriction_reasons` (`reason_id`),
  CONSTRAINT `fk_products_seller` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`seller_id`),
  CONSTRAINT `ck_products_price` CHECK ((`price` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='상품. AI 추출 결과는 검수 후 여기에만 저장';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

