--
-- Table structure for table `recommendation_events`
--

DROP TABLE IF EXISTS `recommendation_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendation_events` (
  `event_id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` varchar(36) NOT NULL,
  `user_id` bigint NOT NULL,
  `group_buy_id` bigint NOT NULL,
  `event_type` varchar(20) NOT NULL COMMENT 'IMPRESSION / CLICK / DETAIL_VIEW',
  `source` varchar(30) NOT NULL DEFAULT 'UNKNOWN',
  `position` int DEFAULT NULL,
  `product_id_snapshot` bigint NOT NULL,
  `brand_snapshot` varchar(100) DEFAULT NULL,
  `category_id_snapshot` bigint DEFAULT NULL,
  `recruitment_rate` decimal(7,6) NOT NULL,
  `discount_rate` decimal(7,6) NOT NULL,
  `deadline_urgency` decimal(7,6) NOT NULL,
  `occurred_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`event_id`),
  KEY `idx_recommendation_events_user_time` (`user_id`,`occurred_at`),
  KEY `idx_recommendation_events_session_time` (`session_id`,`occurred_at`),
  KEY `idx_recommendation_events_group_type` (`group_buy_id`,`event_type`),
  KEY `fk_recommendation_events_product` (`product_id_snapshot`),
  CONSTRAINT `fk_recommendation_events_group_buy` FOREIGN KEY (`group_buy_id`) REFERENCES `group_buys` (`group_buy_id`),
  CONSTRAINT `fk_recommendation_events_product` FOREIGN KEY (`product_id_snapshot`) REFERENCES `products` (`product_id`),
  CONSTRAINT `fk_recommendation_events_session` FOREIGN KEY (`session_id`) REFERENCES `recommendation_sessions` (`session_id`),
  CONSTRAINT `fk_recommendation_events_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `ck_recommendation_event_type` CHECK ((`event_type` in (_utf8mb4'IMPRESSION',_utf8mb4'CLICK',_utf8mb4'DETAIL_VIEW'))),
  CONSTRAINT `ck_recommendation_position` CHECK (((`position` is null) or (`position` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=1606 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='추천 학습용 노출·클릭·상세조회 로그';
/*!40101 SET character_set_client = @saved_cs_client */;

