--
-- Table structure for table `refunds`
--

DROP TABLE IF EXISTS `refunds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `refunds` (
  `refund_id` bigint NOT NULL AUTO_INCREMENT,
  `participation_id` bigint DEFAULT NULL COMMENT '미매칭 입금 환불 시 NULL',
  `return_id` bigint DEFAULT NULL,
  `deposit_id` bigint DEFAULT NULL,
  `payment_id` bigint DEFAULT NULL COMMENT '참여 없이 결제 단위로 개시된 환불(승인 후 공구종료 등)',
  `amount` bigint NOT NULL COMMENT 'KRW 기준',
  `reason_type` varchar(30) NOT NULL COMMENT 'RECRUIT_FAILED/PARTICIPATION_CANCEL/SLOT_EXPIRED/RETURN/SELLER_FAULT/UNMATCHED_DEPOSIT',
  `refund_method` varchar(20) NOT NULL COMMENT 'CARD_CANCEL / ACCOUNT_TRANSFER / KAKAOPAY / CRYPTO',
  `institution_tx_no` varchar(20) DEFAULT NULL COMMENT 'SSAFY 요청 기관거래고유번호',
  `ssafy_transaction_no` bigint DEFAULT NULL COMMENT 'SSAFY 거래고유번호',
  `to_account_no` varchar(16) DEFAULT NULL COMMENT '계좌 이체 환불 시',
  `to_address` varchar(42) DEFAULT NULL COMMENT '코인 환불 수취 주소',
  `asset_amount` decimal(36,18) DEFAULT NULL,
  `tx_hash` varchar(66) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PROCESSING' COMMENT 'PROCESSING / COMPLETED / FAILED',
  `refund_marker` char(1) DEFAULT NULL COMMENT 'PROCESSING/COMPLETED일 때 Y, FAILED면 NULL (중복 환불 차단)',
  `fail_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `processed_at` datetime DEFAULT NULL,
  `execution_claimed` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`refund_id`),
  UNIQUE KEY `uk_refunds_tx` (`tx_hash`),
  UNIQUE KEY `uk_refunds_active_participation` (`participation_id`,`refund_marker`),
  UNIQUE KEY `uk_refunds_active_deposit` (`deposit_id`,`refund_marker`),
  UNIQUE KEY `uk_refunds_active_payment` (`payment_id`,`refund_marker`),
  KEY `idx_refunds_participation` (`participation_id`),
  KEY `idx_refunds_status` (`status`,`created_at`),
  KEY `fk_refunds_return` (`return_id`),
  CONSTRAINT `fk_refunds_deposit` FOREIGN KEY (`deposit_id`) REFERENCES `crypto_deposits` (`deposit_id`),
  CONSTRAINT `fk_refunds_participation` FOREIGN KEY (`participation_id`) REFERENCES `participations` (`participation_id`),
  CONSTRAINT `fk_refunds_payment` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`payment_id`),
  CONSTRAINT `fk_refunds_return` FOREIGN KEY (`return_id`) REFERENCES `return_requests` (`return_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='환불. 카드 취소 실패 시 계좌 이체로 폴백';
/*!40101 SET character_set_client = @saved_cs_client */;

