  `return_id` bigint NOT NULL AUTO_INCREMENT,
  `participation_id` bigint NOT NULL,
  `reason_type` varchar(20) NOT NULL COMMENT 'CHANGE_OF_MIND / DEFECT',
  `reason_detail` varchar(500) DEFAULT NULL,
  `return_shipping_fee` bigint NOT NULL DEFAULT '0' COMMENT '배송비 x2 (왕복)',
  `fee_bearer` varchar(10) NOT NULL COMMENT 'BUYER / SELLER',
  `refund_amount` bigint NOT NULL DEFAULT '0',
  `post_confirm` tinyint(1) NOT NULL DEFAULT '0' COMMENT '구매확정 후 요청 → 관리자 검토 대상',
  `admin_review_required` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(20) NOT NULL DEFAULT 'REQUESTED' COMMENT 'REQUESTED/APPROVED/PICKED_UP/REFUNDED/REJECTED/DISPUTED',
  `requested_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `auto_approve_at` datetime DEFAULT NULL COMMENT '판매자 무응답 자동 승인 예정 시각',
  `auto_refund_due_at` datetime DEFAULT NULL COMMENT '신청 + 7일. 경과 시 자동 환불',
  `approved_at` datetime DEFAULT NULL,
  `approve_type` varchar(10) DEFAULT NULL COMMENT 'MANUAL / AUTO',
  `picked_up_at` datetime DEFAULT NULL COMMENT '판매자 직접 수거 확인',
  `auto_refunded` tinyint(1) NOT NULL DEFAULT '0' COMMENT '수거 미확인 상태로 7일 경과하여 자동 환불',
  `forced_by` bigint DEFAULT NULL COMMENT '관리자 강제 처리',
  `forced_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(255) DEFAULT NULL,
  `pickup_zipcode` char(5) DEFAULT NULL,
  `pickup_address1` varchar(255) DEFAULT NULL,
  `pickup_address2` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`return_id`),
  KEY `idx_returns_participation` (`participation_id`),
  KEY `idx_returns_auto_refund` (`status`,`auto_refund_due_at`),
  KEY `idx_returns_review` (`admin_review_required`,`requested_at`),
  KEY `fk_returns_admin` (`forced_by`),
  KEY `idx_returns_auto_approve` (`status`,`admin_review_required`,`auto_approve_at`),
  CONSTRAINT `fk_returns_admin` FOREIGN KEY (`forced_by`) REFERENCES `admins` (`admin_id`),
  CONSTRAINT `fk_returns_participation` FOREIGN KEY (`participation_id`) REFERENCES `participations` (`participation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='반품. 수거 미확인 7일 경과 시 자동 환불';
/*!40101 SET character_set_client = @saved_cs_client */;

