--
-- Table structure for table `settlements`
--

DROP TABLE IF EXISTS `settlements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `settlements` (
  `settlement_id` bigint NOT NULL AUTO_INCREMENT,
  `group_buy_id` bigint NOT NULL,
  `seller_id` bigint NOT NULL,
  `round_no` int NOT NULL DEFAULT '1' COMMENT '일 1회 배치 회차',
  `confirmed_count` int NOT NULL DEFAULT '0',
  `share_total` bigint NOT NULL DEFAULT '0',
  `shipping_total` bigint NOT NULL DEFAULT '0',
  `rounding_diff` bigint NOT NULL DEFAULT '0',
  `platform_fee_rate` decimal(5,4) NOT NULL COMMENT '스냅샷',
  `platform_fee` bigint NOT NULL DEFAULT '0' COMMENT 'share_total x rate (배송비 제외)',
  `settlement_amount` bigint NOT NULL DEFAULT '0',
  `status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / COMPLETED / HOLD',
  `transfer_status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT 'SSAFY 계좌 이체 상태',
  `institution_tx_no` varchar(20) DEFAULT NULL COMMENT '이체 요청 기관거래고유번호',
  `withdrawal_tx_no` bigint DEFAULT NULL COMMENT '출금 거래고유번호',
  `deposit_tx_no` bigint DEFAULT NULL COMMENT '입금 거래고유번호',
  `transferred_at` datetime DEFAULT NULL,
  `transfer_fail_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `transfer_claimed` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`settlement_id`),
  UNIQUE KEY `uk_settlements_round` (`group_buy_id`,`round_no`),
  KEY `idx_settlements_seller` (`seller_id`,`status`),
  KEY `idx_settlements_transfer` (`transfer_status`,`created_at`),
  CONSTRAINT `fk_settlements_group_buy` FOREIGN KEY (`group_buy_id`) REFERENCES `group_buys` (`group_buy_id`),
  CONSTRAINT `fk_settlements_seller` FOREIGN KEY (`seller_id`) REFERENCES `seller_profiles` (`seller_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='판매자 정산. 플랫폼 계좌 → 판매자 계좌 SSAFY 이체';
/*!40101 SET character_set_client = @saved_cs_client */;

