  KEY `idx_ssafy_called` (`called_at`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='기관거래고유번호 유일성 보장 및 호출 이력 (H1007 방지)';
