--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `user_id` bigint NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `nickname` varchar(50) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `phone_verified` tinyint(1) NOT NULL DEFAULT '0',
  `ssafy_user_key` varchar(60) DEFAULT NULL COMMENT 'SSAFY member 생성 응답 userKey',
  `ssafy_account_no` varchar(16) DEFAULT NULL COMMENT '카드 취소 불가 시 환불 수취 계좌',
  `wallet_address` varchar(42) DEFAULT NULL COMMENT '최근 사용 MetaMask 주소',
  `is_seller` tinyint(1) NOT NULL DEFAULT '0' COMMENT '판매자 여부 캐시',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE / DORMANT / WITHDRAWN',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uk_users_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='통합 사용자 계정';
/*!40101 SET character_set_client = @saved_cs_client */;

